<?php
/** Native canvas media and drama Agent proposals, private normal-login HTTP only. */
function runMarketAgentMediaHttp($f,string $api,string $peer,string $suffix,string &$token,string $image,int $text,int $agent,array &$report): void
{
    $db=think\facade\Db::class;$t=$f->tenant;$u=$f->user;$script=dirname(__DIR__).'/market-generation-http.php';
    $check=fn($ok,$why)=>MarketWorkerFixture::check((bool)$ok,$why);
    $post=function($path,$p)use($api,$suffix,&$token){return dataHttp($api,'/api/app.'.$path.$suffix,$p,$token);};
    $get=function($path,$p)use($peer,$suffix,&$token){return dataHttp($peer,'/api/app.'.$path.$suffix.'&'.http_build_query($p),[],$token,'GET');};
    $pair=function($path,$p)use($api,$peer,$suffix,&$token,$check){
        $multi=curl_multi_init();$handles=[];foreach([$api,$peer]as$base){$c=curl_init($base.'/api/app.'.$path.$suffix);curl_setopt_array($c,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($p),CURLOPT_HTTPHEADER=>['Content-Type: application/json','token: '.$token],CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>20]);curl_multi_add_handle($multi,$c);$handles[]=$c;}
        do{curl_multi_exec($multi,$active);if($active)curl_multi_select($multi,.01);}while($active);$rows=[];foreach($handles as$c){$rows[]=json_decode((string)curl_multi_getcontent($c),true);curl_multi_remove_handle($multi,$c);curl_close($c);}curl_multi_close($multi);
        $check(($rows[0]['code']??0)===1&&($rows[1]['code']??0)===1,'Media concurrent submission refused: '.json_encode($rows));return array_column($rows,'data');
    };
    $runRows=fn($ids)=>$db::name('aigc_llm_agent_run')->whereIn('id',$ids)->field('id,status,phase,error')->select()->toArray();
    $agentUntil=function($ids,$states=['success'])use($f,$script,$db,$runRows){
        $f->start($script,'fixture_agent_runner','agent');try{MarketWorkerFixture::wait(fn()=>$db::name('aigc_llm_agent_run')->whereIn('id',$ids)->whereNotIn('status',$states)->count()===0,'Canvas media Agent did not reach '.implode('/',$states),40);}catch(Throwable $e){$tools=[];foreach(file($f->dir.'/deep-calls.jsonl')?:[] as $line)foreach(json_decode($line,true)['input']['messages']??[] as $message)if(($message['role']??'')==='tool')$tools[]=$message['content'];throw new RuntimeException($e->getMessage().' '.json_encode([$runRows($ids),array_slice($tools,-8)],JSON_UNESCAPED_UNICODE));}finally{$f->stop('agent');}
    };
    $supplierCalls=fn()=>count(file($f->dir.'/submissions.jsonl')?:[])+count(file($f->dir.'/deep-calls.jsonl')?:[]);
    $videoRow=$db::name('power_market_product')->where(['resource_type'=>'model','model_type'=>'video'])->find();$video='market_video_model:'.$videoRow['id'];$videoSku=(int)$db::name('power_market_sku')->where('product_id',$videoRow['id'])->value('id');
    $payload=json_decode($videoRow['source_payload'],true);$payload['market_metadata']['params_schema']['properties']['image_url']=['type'=>'string'];$payload['market_metadata']['material_capabilities']['modes'][]=['code'=>'image_to_video','method'=>'image_to_video','fields'=>[['field'=>'image_url','kind'=>'image','role'=>'first','required'=>true,'minimum'=>1,'maximum'=>1]]];
    $db::name('power_market_product')->where('id',$videoRow['id'])->update(['source_payload'=>json_encode($payload)]);
    $props=[];foreach(['prompt','lyric','style','vocal_gender','language','title']as$key)$props[$key]=['type'=>'string'];foreach(['custom','instrumental']as$key)$props[$key]=['type'=>'boolean'];$props['duration']=['type'=>'integer','enum'=>[5]];
    foreach(['create','query']as$op){$p=app\common\model\power\PowerMarketProduct::create(['product_code'=>$f->prefix.'media_music_'.$op,'name'=>'Private media music '.$op,'resource_type'=>'app_api','model_type'=>'audio','upstream_app_code'=>'music_generation','upstream_api_code'=>$op,'source_code'=>'isolated-fixture','upstream_resource_key'=>$f->prefix.'media_music_'.$op,'source_payload'=>['market_metadata'=>['params_schema'=>['properties'=>$props]]],'status'=>1]);$s=app\common\model\power\PowerMarketSku::create(['product_id'=>$p['id'],'sku_key'=>$f->prefix.'media_music_'.$op,'title'=>'Private music','locked_params'=>$op==='create'?['type'=>'generate','duration'=>5]:[],'usage_unit'=>'per_call','usage_unit_size'=>1,'sale_points'=>1,'upstream_price'=>1,'sale_status'=>1,'status'=>1]);if($op==='create')$musicSku=(int)$s['id'];}
    $nodes=[['id'=>'anchor_a','type'=>'text','position'=>['x'=>0,'y'=>0],'metadata'=>['content'=>'Page A anchor']],['id'=>'anchor_b','type'=>'text','position'=>['x'=>0,'y'=>0],'metadata'=>['content'=>'Page B anchor']]];
    $pages=[['id'=>'page_a','name'=>'A','nodeIds'=>['anchor_a'],'viewport'=>['x'=>0,'y'=>0,'k'=>1]],['id'=>'page_b','name'=>'B','nodeIds'=>['anchor_b'],'viewport'=>['x'=>0,'y'=>0,'k'=>1]]];
    $project=$post('aigc_canvas.project/create',['name'=>'Private multi-page Agent media','nodes'=>$nodes,'edges'=>[],'viewport'=>['currentCanvasId'=>'page_b','pages'=>$pages]]);$id=(int)$project['id'];$stale=$project;
    $a=['project_id'=>$id,'page_id'=>'page_a'];$b=['project_id'=>$id,'page_id'=>'page_b'];$preferences=['mode'=>'ask','models'=>['text'=>'market_text_'.$agent,'video'=>$video,'image'=>$image]];
    $videoInput=$a+['session_id'=>0,'request_id'=>'media-video-page-a-request-0001','content'=>'Synthetic media video','preferences'=>$preferences];[$v,$same]=$pair('aigc_canvas.conversation/submit',$videoInput);$check($v['id']===$same['id'],'Video same-key requests created two runs');
    $musicInput=$b+['session_id'=>0,'request_id'=>'media-music-page-b-request-0002','content'=>'Synthetic media music','preferences'=>$preferences];[$m,$same]=$pair('aigc_canvas.conversation/submit',$musicInput);$check($m['id']===$same['id'],'Music same-key requests created two runs');
    $agentUntil([$v['id'],$m['id']],['awaiting_confirmation']);$report['two_page_video_music_parallel_admission_and_plans']=true;
    foreach([[$a,$v],[$b,$m]]as[$scope,$run]){$plan=$get('aigc_canvas.conversation/detail',$scope+['run_id'=>$run['id']]);$pair('aigc_canvas.conversation/confirm',$scope+['run_id'=>$run['id'],'approval_hash'=>$plan['approval_hash']]);}
    $f->start($script,'fixture_agent_runner','agent');MarketWorkerFixture::wait(fn()=>$db::name('aigc_llm_agent_run')->whereIn('id',[$v['id'],$m['id']])->where('status','waiting_tasks')->count()===2,'Two media plans not bound',40);$f->stop('agent',true);
    $vTask=(int)$db::name('aigc_llm_agent_step')->where('run_id',$v['id'])->value('task_id');$mTask=(int)$db::name('aigc_llm_agent_step')->where('run_id',$m['id'])->value('task_id');
    $frozen=$db::name('ai_consumption_log')->order('id')->column('price_snapshot','id');$db::name('power_market_sku')->whereIn('id',[$videoSku,$musicSku])->update(['sale_status'=>0,'sale_points'=>99]);
    $f->start($script,'');MarketWorkerFixture::wait(fn()=>$db::name('aigc_video_task')->where('id',$vTask)->value('status')==='success'&&$db::name('aigc_music_task')->where('id',$mTask)->value('status')==='success','Native video/music not finished while Agent offline',50);$f->stop();$agentUntil([$v['id'],$m['id']]);
    $page=$get('aigc_canvas.project/detail',['id'=>$id]);$pageIds=array_column($page['viewport']['pages'],'nodeIds','id');$check(count($pageIds['page_a'])===2&&count($pageIds['page_b'])===3,'Media were written to the active page instead of their original pages');
    foreach([[$a,$v,'video',1],[$b,$m,'audio',2]]as[$scope,$run,$kind,$count]){$art=$get('aigc_canvas.conversation/artifacts',$scope+['session_id'=>$run['session_id']]);$check(count($art)===$count&&count(array_filter($art,fn($x)=>$x['kind']===$kind))===$count,'Native media output count or kind lost');foreach($art as$x){$n=array_values(array_filter($page['nodes'],fn($n)=>($n['metadata']['agentArtifactId']??0)===$x['id']))[0]??[];$check(in_array($n['id']??'', $pageIds[$scope['page_id']],true)&&!empty($n['metadata']['agentGeneration']['task_id']),'Artifact has no original page or native generation settings');}}
    $check($frozen===$db::name('ai_consumption_log')->order('id')->column('price_snapshot','id'),'Accepted video/music frozen prices changed');$report['video_music_native_worker_restart_two_audio_outputs_frozen']=true;
    $before=$supplierCalls();$check($post('aigc_canvas.conversation/submit',$videoInput)['id']===$v['id']&&$post('aigc_canvas.conversation/submit',$musicInput)['id']===$m['id']&&$supplierCalls()===$before,'Completed multi-page history submitted again');$report['two_page_history_replay_no_generation']=true;
    $bad=callHttp($peer,'/api/app.aigc_canvas.conversation/detail'.$suffix.'&'.http_build_query($b+['run_id'=>$v['id']]),[],$token,'GET');$check(($bad['code']??1)!==1,'Page B read Page A run');
    $bad=callHttp($api,'/api/app.aigc_canvas.project/save'.$suffix,['id'=>$id,'nodes'=>$stale['nodes'],'edges'=>[],'viewport'=>$stale['viewport']],$token);$check(($bad['code']??1)!==1,'Stale save removed Agent media');
    $page['viewport']['currentCanvasId']='page_a';$page=$post('aigc_canvas.project/save',['id'=>$id,'nodes'=>$page['nodes'],'edges'=>$page['edges'],'viewport'=>$page['viewport']]);$check(array_column($page['viewport']['pages'],'nodeIds','id')===$pageIds,'Switching active page moved result nodes');$report['stale_save_refused_current_page_save_preserves_results']=true;
    $db::name('power_market_sku')->whereIn('id',[$videoSku,$musicSku])->update(['sale_status'=>1,'sale_points'=>1]);
    $old=$db::name('aigc_llm_agent_run')->where('id',$v['id'])->find();$new=$post('aigc_canvas.conversation/submit',array_replace($videoInput,['session_id'=>$v['session_id'],'request_id'=>'media-video-history-request-0003']));$agentUntil([$new['id']],['awaiting_confirmation']);$plan=$get('aigc_canvas.conversation/detail',$a+['run_id'=>$new['id']]);$post('aigc_canvas.conversation/confirm',$a+['run_id'=>$new['id'],'approval_hash'=>$plan['approval_hash']]);$f->start($script,'');$agentUntil([$new['id']]);$f->stop();$check($old===$db::name('aigc_llm_agent_run')->where('id',$v['id'])->find(),'New historical video attempt overwrote old run');$report['historical_video_new_attempt_keeps_old_run']=true;
    // Page removal before and after native admission are separate boundaries.
    foreach(['before','after']as$when){$page=$get('aigc_canvas.project/detail',['id'=>$id]);$drop='drop_'.$when;$page['viewport']['pages'][]=['id'=>$drop,'name'=>$drop,'nodeIds'=>[],'viewport'=>['x'=>0,'y'=>0,'k'=>1]];$post('aigc_canvas.project/save',['id'=>$id,'nodes'=>$page['nodes'],'edges'=>$page['edges'],'viewport'=>$page['viewport']]);$scope=['project_id'=>$id,'page_id'=>$drop];$r=$post('aigc_canvas.conversation/submit',$scope+['session_id'=>0,'request_id'=>'media-drop-'.$when.'-request-0004','content'=>'Synthetic media video','preferences'=>$preferences]);$agentUntil([$r['id']],['awaiting_confirmation']);$plan=$get('aigc_canvas.conversation/detail',$scope+['run_id'=>$r['id']]);
        if($when==='after'){$post('aigc_canvas.conversation/confirm',$scope+['run_id'=>$r['id'],'approval_hash'=>$plan['approval_hash']]);$f->start($script,'fixture_agent_runner','agent');MarketWorkerFixture::wait(fn()=>$db::name('aigc_llm_agent_run')->where('id',$r['id'])->value('status')==='waiting_tasks','Removed-page video did not bind',35);$f->stop('agent');}
        $page=$get('aigc_canvas.project/detail',['id'=>$id]);$page['viewport']['pages']=array_values(array_filter($page['viewport']['pages'],fn($p)=>$p['id']!==$drop));$post('aigc_canvas.project/save',['id'=>$id,'nodes'=>$page['nodes'],'edges'=>$page['edges'],'viewport'=>$page['viewport']]);
        if($when==='before'){$before=$supplierCalls();$denied=callHttp($api,'/api/app.aigc_canvas.conversation/confirm'.$suffix,$scope+['run_id'=>$r['id'],'approval_hash'=>$plan['approval_hash']],$token);$check(($denied['code']??1)!==1,'Deleted page plan was admitted');$agentUntil([$r['id']],['canceled']);$check($before===$supplierCalls(),'Deleted unconfirmed page generated');$report['page_removed_before_confirm_no_native_submit']=true;}
        else{$f->start($script,'');$agentUntil([$r['id']],['success','canceled','partial_success']);$f->stop();$step=$db::name('aigc_llm_agent_step')->where('run_id',$r['id'])->find();$check($step['status']==='success'&&$db::name('aigc_llm_agent_artifact')->where('run_id',$r['id'])->count()===1,'Removed page lost the accepted result');$report['page_removed_after_admission_native_result_retained']=true;}
    }
    $login=dataHttp($peer,'/api/login/account'.$suffix,['account'=>$f->prefix,'password'=>'Private-fixture-pass-2026','scene'=>1,'terminal'=>4]);$token=$login['token'];$reopened=$get('aigc_canvas.project/detail',['id'=>$id]);$check(count($reopened['viewport']['pages'])===2,'Normal login reopen restored removed pages');$report['normal_login_multi_page_reopen']=true;
    $report['phase']='canvas_complete';
}
